package com.example.ancapp.model

import java.time.LocalDate
import java.time.Period
import java.time.temporal.ChronoUnit

enum class DangerSign(val label: String) {
  NONE("None"),
  VAGINAL_BLEEDING("Vaginal bleeding"),
  SEVERE_HEADACHE("Severe headache"),
  BLURRED_VISION("Blurred vision"),
  FEVER("Fever");

  companion object {
    fun fromNameOrNull(name: String): DangerSign? =
      entries.find { it.name.equals(name.trim(), ignoreCase = true) }

    fun serializeList(signs: List<DangerSign>): String {
      val normalized = if (signs.isEmpty()) listOf(NONE) else signs
      return normalized.joinToString(",") { it.name }
    }

    fun deserializeList(serialized: String?): List<DangerSign> {
      if (serialized.isNullOrBlank()) return listOf(NONE)
      val parsed = serialized.split(",")
        .mapNotNull { fromNameOrNull(it) }
        .distinct()
      return if (parsed.isEmpty()) listOf(NONE) else parsed
    }
  }
}

data class AncVisit(
  val id: Long = 0L,
  val patientId: Long,
  val visitDate: LocalDate,
  val gestationalAgeWeeks: Int,
  val weightKg: Double,
  val systolicBp: Int,
  val diastolicBp: Int,
  val hemoglobinGdl: Double? = null,
  val dangerSigns: List<DangerSign> = listOf(DangerSign.NONE),
  val notes: String = ""
) {
  val formattedBp: String
    get() = "$systolicBp/$diastolicBp mmHg"

  val hasActiveDangerSigns: Boolean
    get() = dangerSigns.any { it != DangerSign.NONE }

  val formattedDangerSigns: String
    get() = if (dangerSigns.isEmpty() || (dangerSigns.size == 1 && dangerSigns.first() == DangerSign.NONE)) {
      DangerSign.NONE.label
    } else {
      dangerSigns.filter { it != DangerSign.NONE }.joinToString(", ") { it.label }
    }
}

data class Patient(
  val id: Long = 0L,
  val name: String,
  val dateOfBirth: LocalDate,
  val estimatedDueDate: LocalDate
) {
  fun ageYears(referenceDate: LocalDate = LocalDate.now()): Int {
    return Period.between(dateOfBirth, referenceDate).years.coerceAtLeast(0)
  }

  fun currentPregnancyWeeks(referenceDate: LocalDate = LocalDate.now()): Int {
    return Companion.calculateGestationalWeeks(estimatedDueDate, referenceDate)
  }

  companion object {
    /**
     * Standard 40-week (280-day) gestation calculation based on Estimated Due Date (EDD).
     */
    fun calculateGestationalWeeks(
      estimatedDueDate: LocalDate,
      onDate: LocalDate = LocalDate.now()
    ): Int {
      val daysUntilDue = ChronoUnit.DAYS.between(onDate, estimatedDueDate)
      val gestationalDays = 280L - daysUntilDue
      return (gestationalDays / 7L).toInt().coerceIn(1, 45)
    }
  }
}

data class PatientWithVisits(
  val patient: Patient,
  val visits: List<AncVisit>
) {
  val lastVisit: AncVisit?
    get() = visits.maxWithOrNull(compareBy<AncVisit> { it.visitDate }.thenBy { it.id })
}

package com.example.ancapp.ui

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import com.example.ancapp.data.AncDatabaseHelper
import com.example.ancapp.model.AncVisit
import com.example.ancapp.model.PatientWithVisits
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

sealed interface Screen {
  data object Register : Screen
  data class PatientDetail(val patientId: Long) : Screen
  data class RecordVisit(val patientId: Long) : Screen
}

data class AncUiState(
  val patients: List<PatientWithVisits> = emptyList(),
  val currentScreen: Screen = Screen.Register,
  val lastSavedMessage: String? = null
) {
  fun selectedPatient(patientId: Long): PatientWithVisits? =
    patients.find { it.patient.id == patientId }
}

class AncViewModel(application: Application) : AndroidViewModel(application) {
  private val dbHelper = AncDatabaseHelper.getInstance(application)

  private val _uiState = MutableStateFlow(AncUiState())
  val uiState: StateFlow<AncUiState> = _uiState.asStateFlow()

  init {
    refreshPatients()
  }

  fun refreshPatients() {
    val allPatients = dbHelper.getAllPatientsSortedByDueDate()
    _uiState.update { it.copy(patients = allPatients) }
  }

  fun openPatientDetail(patientId: Long) {
    _uiState.update {
      it.copy(
        currentScreen = Screen.PatientDetail(patientId),
        lastSavedMessage = null
      )
    }
  }

  fun openRecordVisit(patientId: Long) {
    _uiState.update {
      it.copy(
        currentScreen = Screen.RecordVisit(patientId),
        lastSavedMessage = null
      )
    }
  }

  fun navigateBack(): Boolean {
    val current = _uiState.value.currentScreen
    return when (current) {
      is Screen.RecordVisit -> {
        _uiState.update { it.copy(currentScreen = Screen.PatientDetail(current.patientId)) }
        true
      }
      is Screen.PatientDetail -> {
        _uiState.update {
          it.copy(
            currentScreen = Screen.Register,
            lastSavedMessage = null
          )
        }
        true
      }
      Screen.Register -> false
    }
  }

  fun clearMessage() {
    _uiState.update { it.copy(lastSavedMessage = null) }
  }

  fun saveVisit(visit: AncVisit) {
    dbHelper.insertVisit(visit)
    val updatedPatients = dbHelper.getAllPatientsSortedByDueDate()
    _uiState.update {
      it.copy(
        patients = updatedPatients,
        currentScreen = Screen.PatientDetail(visit.patientId),
        lastSavedMessage = "Visit on ${visit.visitDate} recorded."
      )
    }
  }
}

