    String.format(Locale.US, "%.1f kg", visit.weightKg)
  }
  val formattedHb = remember(visit.hemoglobinGdl) {
    visit.hemoglobinGdl?.let { String.format(Locale.US, "%.1f g/dL", it) }
  }

  Card(
    modifier = Modifier
      .fillMaxWidth()
      .testTag("visit_card_${visit.id}"),
    shape = RoundedCornerShape(12.dp),
    colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
    elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
    border = BorderStroke(
      1.dp,
      if (visit.hasActiveDangerSigns) MaterialTheme.colorScheme.error else MaterialTheme.colorScheme.surfaceVariant
    )
  ) {
    Column(modifier = Modifier.padding(16.dp)) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
      ) {
        Row(verticalAlignment = Alignment.CenterVertically) {
          Icon(
            imageVector = Icons.Default.CalendarMonth,
            contentDescription = null,
            tint = MaterialTheme.colorScheme.primary,
            modifier = Modifier.size(20.dp)
          )
          Spacer(modifier = Modifier.width(6.dp))
          Text(
            text = visit.visitDate.toString(),
            style = MaterialTheme.typography.titleMedium,
            fontWeight = FontWeight.Bold
          )
        }

        Surface(
          color = MaterialTheme.colorScheme.tertiaryContainer,
          shape = RoundedCornerShape(16.dp)
        ) {
          Text(
            text = "${visit.gestationalAgeWeeks} weeks GA",
            style = MaterialTheme.typography.labelMedium,
            fontWeight = FontWeight.SemiBold,
            color = MaterialTheme.colorScheme.onTertiaryContainer,
            modifier = Modifier.padding(horizontal = 10.dp, vertical = 4.dp)
          )
        }
      }

      Spacer(modifier = Modifier.height(12.dp))

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(12.dp)
      ) {
        MetricBox(
          label = "Weight",
          value = formattedWeight,
          modifier = Modifier.weight(1f)
        )
        MetricBox(
          label = "Blood Pressure",
          value = "${visit.systolicBp}/${visit.diastolicBp} mmHg",
          modifier = Modifier.weight(1f)
        )
        if (formattedHb != null) {
          MetricBox(
            label = "Hemoglobin",
            value = formattedHb,
            modifier = Modifier.weight(1f)
          )
        }
      }

      Spacer(modifier = Modifier.height(10.dp))

      Surface(
        color = if (visit.hasActiveDangerSigns) {
          MaterialTheme.colorScheme.errorContainer
        } else {
          MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.5f)
        },
        shape = RoundedCornerShape(8.dp),
        modifier = Modifier.fillMaxWidth()
      ) {
        Row(
          modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
          verticalAlignment = Alignment.CenterVertically
        ) {
          if (visit.hasActiveDangerSigns) {
            Icon(
              imageVector = Icons.Default.Warning,
              contentDescription = null,
              tint = MaterialTheme.colorScheme.error,
              modifier = Modifier.size(16.dp)
            )
            Spacer(modifier = Modifier.width(6.dp))
          }
          Text(
            text = "Danger signs: ${visit.formattedDangerSigns}",
            style = MaterialTheme.typography.bodySmall,
            fontWeight = if (visit.hasActiveDangerSigns) FontWeight.Bold else FontWeight.Normal,
            color = if (visit.hasActiveDangerSigns) {
              MaterialTheme.colorScheme.onErrorContainer
            } else {
              MaterialTheme.colorScheme.onSurfaceVariant
            }
          )
        }
      }

      if (visit.notes.isNotBlank()) {
        Spacer(modifier = Modifier.height(8.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodyMedium,
          color = MaterialTheme.colorScheme.onSurface
        )
      }
    }
  }
}

