@OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)
@Composable
fun RecordVisitScreen(
  patientWithVisits: PatientWithVisits,
  onCancelClick: () -> Unit,
  onSaveVisit: (AncVisit) -> Unit
) {
  val patient = patientWithVisits.patient
  val context = LocalContext.current
  val today = remember { LocalDate.now() }
  val suggestedWeeks = remember(patient) { patient.currentPregnancyWeeks(today) }

  var visitDateText by rememberSaveable { mutableStateOf(today.toString()) }
  var gestationalWeeksText by rememberSaveable { mutableStateOf("") }
  var weightKgText by rememberSaveable { mutableStateOf("") }
  var systolicBpText by rememberSaveable { mutableStateOf("") }
  var diastolicBpText by rememberSaveable { mutableStateOf("") }
  var hemoglobinText by rememberSaveable { mutableStateOf("") }
  var notesText by rememberSaveable { mutableStateOf("") }

  val selectedDangerSigns = remember {
    mutableStateListOf(DangerSign.NONE)
  }

  var errorMessage by rememberSaveable { mutableStateOf<String?>(null) }

  fun toggleDangerSign(sign: DangerSign) {
    if (sign == DangerSign.NONE) {
      selectedDangerSigns.clear()
      selectedDangerSigns.add(DangerSign.NONE)
    } else {
      selectedDangerSigns.remove(DangerSign.NONE)
      if (selectedDangerSigns.contains(sign)) {
        selectedDangerSigns.remove(sign)
        if (selectedDangerSigns.isEmpty()) {
          selectedDangerSigns.add(DangerSign.NONE)
        }
      } else {
        selectedDangerSigns.add(sign)
      }
    }
  }

  fun openDatePicker() {
    val initialDate = parseFlexibleDate(visitDateText) ?: today
    DatePickerDialog(
      context,
      { _, year, month, dayOfMonth ->
        visitDateText = LocalDate.of(year, month + 1, dayOfMonth).toString()
      },
      initialDate.year,
      initialDate.monthValue - 1,
      initialDate.dayOfMonth
    ).show()
  }

  fun handleSave() {
    val parsedDate = if (visitDateText.isBlank()) {
      today
    } else {
      parseFlexibleDate(visitDateText)
    }
    if (parsedDate == null) {
      errorMessage = "Please enter a valid visit date (YYYY-MM-DD)."
      return
    }

    val gaWeeks = if (gestationalWeeksText.isBlank()) {
      Patient.calculateGestationalWeeks(patient.estimatedDueDate, parsedDate)
    } else {
      gestationalWeeksText.trim().toIntOrNull()
    }
    if (gaWeeks == null || gaWeeks !in 1..48) {
      errorMessage = "Please enter a valid gestational age in weeks (1-48)."
      return
    }

    val weight = weightKgText.trim().toDoubleOrNull()
    if (weight == null || weight <= 0.0) {
      errorMessage = "Please enter a valid weight in kg."
      return
    }

    val systolic = systolicBpText.trim().toIntOrNull()
    val diastolic = diastolicBpText.trim().toIntOrNull()
    if (systolic == null || systolic <= 0 || diastolic == null || diastolic <= 0) {
      errorMessage = "Please enter valid systolic and diastolic blood pressure (mmHg)."
      return
    }

    val hb: Double? = if (hemoglobinText.isBlank()) {
      null
    } else {
      val parsedHb = hemoglobinText.trim().toDoubleOrNull()
      if (parsedHb == null || parsedHb <= 0.0) {
        errorMessage = "Please enter a valid hemoglobin value (g/dL) or leave blank."
        return
      }
      parsedHb
    }

    errorMessage = null
    onSaveVisit(
      AncVisit(
        patientId = patient.id,
        visitDate = parsedDate,
        gestationalAgeWeeks = gaWeeks,
        weightKg = weight,
        systolicBp = systolic,
        diastolicBp = diastolic,
        hemoglobinGdl = hb,
        dangerSigns = selectedDangerSigns.toList(),
        notes = notesText.trim()
      )
    )
  }

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text(
              text = "Record ANC Visit",
              style = MaterialTheme.typography.titleLarge,
              fontWeight = FontWeight.Bold
            )
            Text(
              text = "${patient.name} • Due ${patient.estimatedDueDate}",
              style = MaterialTheme.typography.labelMedium,
              color = MaterialTheme.colorScheme.onPrimary.copy(alpha = 0.85f)
            )
          }
        },
        navigationIcon = {
          IconButton(
            onClick = onCancelClick,
            modifier = Modifier.testTag("cancel_visit_button")
          ) {
            Icon(
              imageVector = Icons.AutoMirrored.Filled.ArrowBack,
              contentDescription = "Back",
              tint = MaterialTheme.colorScheme.onPrimary
            )
          }
        },
        colors = TopAppBarDefaults.topAppBarColors(
          containerColor = MaterialTheme.colorScheme.primary,
          titleContentColor = MaterialTheme.colorScheme.onPrimary
        )
      )
    },
    bottomBar = {
      Surface(
        tonalElevation = 4.dp,
        shadowElevation = 6.dp,
        color = MaterialTheme.colorScheme.surface
      ) {
        Row(
          modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 10.dp),
          horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
          OutlinedButton(
            onClick = onCancelClick,
            modifier = Modifier.weight(1f),
            shape = RoundedCornerShape(10.dp)
          ) {
            Text("Cancel")
          }
          Button(
            onClick = { handleSave() },
            modifier = Modifier
              .weight(2f)
              .testTag("save_visit_button"),
            shape = RoundedCornerShape(10.dp)
          ) {
            Text(
              text = "Save Visit",
              fontWeight = FontWeight.Bold
            )
          }
        }
      }
    }
  ) { innerPadding ->
    Column(
      modifier = Modifier
        .fillMaxSize()
        .padding(innerPadding)
        .verticalScroll(rememberScrollState())
        .padding(horizontal = 16.dp, vertical = 12.dp),
      verticalArrangement = Arrangement.spacedBy(10.dp)
    ) {
      if (errorMessage != null) {
        Surface(
          color = MaterialTheme.colorScheme.errorContainer,
          shape = RoundedCornerShape(8.dp),
          modifier = Modifier.fillMaxWidth()
        ) {
          Text(
            text = errorMessage!!,
            color = MaterialTheme.colorScheme.onErrorContainer,
            style = MaterialTheme.typography.bodySmall,
            fontWeight = FontWeight.SemiBold,
            modifier = Modifier.padding(10.dp)
          )
        }
      }

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(10.dp)
      ) {
        OutlinedTextField(
          value = visitDateText,
          onValueChange = { visitDateText = it },
          label = { Text("Visit Date (YYYY-MM-DD)") },
          placeholder = { Text(today.toString()) },
          singleLine = true,
          trailingIcon = {
            IconButton(onClick = { openDatePicker() }) {
              Icon(
                imageVector = Icons.Default.CalendarMonth,
                contentDescription = "Select Date"
              )
            }
          },
          modifier = Modifier
            .weight(1.2f)
            .testTag("input_visit_date")
        )

        OutlinedTextField(
          value = gestationalWeeksText,
          onValueChange = { gestationalWeeksText = it },
          label = { Text("Gestational Age (weeks)") },
          placeholder = { Text("$suggestedWeeks") },
          singleLine = true,
          keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
          modifier = Modifier
            .weight(1f)
            .testTag("input_gestational_weeks")
        )
      }

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(10.dp)
      ) {
        OutlinedTextField(
          value = weightKgText,
          onValueChange = { weightKgText = it },
          label = { Text("Weight (kg)") },
          placeholder = { Text("e.g. 68.5") },
          singleLine = true,
          keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
          modifier = Modifier
            .weight(1f)
            .testTag("input_weight_kg")
        )

        OutlinedTextField(
          value = hemoglobinText,
          onValueChange = { hemoglobinText = it },
          label = { Text("Hemoglobin (g/dL, optional)") },
          placeholder = { Text("e.g. 11.8") },
          singleLine = true,
          keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
          modifier = Modifier
            .weight(1f)
            .testTag("input_hemoglobin")
        )
      }

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.spacedBy(10.dp)
      ) {
        OutlinedTextField(
          value = systolicBpText,
          onValueChange = { systolicBpText = it },
          label = { Text("Systolic BP (mmHg)") },
          placeholder = { Text("e.g. 120") },
          singleLine = true,
          keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
          modifier = Modifier
            .weight(1f)
            .testTag("input_systolic_bp")
        )

        OutlinedTextField(
          value = diastolicBpText,
          onValueChange = { diastolicBpText = it },
          label = { Text("Diastolic BP (mmHg)") },
          placeholder = { Text("e.g. 80") },
          singleLine = true,
          keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
          modifier = Modifier
            .weight(1f)
            .testTag("input_diastolic_bp")
        )
      }

      Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(10.dp),
        colors = CardDefaults.cardColors(
          containerColor = MaterialTheme.colorScheme.surface
        ),
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.surfaceVariant)
      ) {
        Column(modifier = Modifier.padding(12.dp)) {
          Text(
            text = "Danger Signs (select all that apply)",
            style = MaterialTheme.typography.titleSmall,
            fontWeight = FontWeight.Bold
          )
          Spacer(modifier = Modifier.height(6.dp))

          FlowRow(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp),
            verticalArrangement = Arrangement.spacedBy(6.dp)
          ) {
            DangerSign.entries.forEach { sign ->
              val isSelected = selectedDangerSigns.contains(sign)
              DangerSignOptionChip(
                sign = sign,
                selected = isSelected,
                onClick = { toggleDangerSign(sign) }
              )
            }
          }
        }
      }

      OutlinedTextField(
        value = notesText,
        onValueChange = { notesText = it },
        label = { Text("Notes") },
        placeholder = { Text("Clinical observations, counseling, follow-up plan...") },
        minLines = 2,
        maxLines = 4,
        modifier = Modifier
          .fillMaxWidth()
          .testTag("input_notes")
      )
    }
  }
}

@Composable
private fun DangerSignOptionChip(
  sign: DangerSign,
  selected: Boolean,
  onClick: () -> Unit
) {
  val isWarningSign = sign != DangerSign.NONE && selected
  Surface(
    shape = RoundedCornerShape(8.dp),
    color = when {
      isWarningSign -> MaterialTheme.colorScheme.errorContainer
      selected -> MaterialTheme.colorScheme.primaryContainer
      else -> MaterialTheme.colorScheme.background
    },
    border = BorderStroke(
      width = 1.dp,
      color = when {
        isWarningSign -> MaterialTheme.colorScheme.error
        selected -> MaterialTheme.colorScheme.primary
        else -> MaterialTheme.colorScheme.surfaceVariant
      }
    ),
    modifier = Modifier
      .clickable(role = Role.Checkbox, onClick = onClick)
      .testTag("danger_sign_${sign.name.lowercase()}")
  ) {
    Row(
      modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
      verticalAlignment = Alignment.CenterVertically
    ) {
      Checkbox(
        checked = selected,
        onCheckedChange = null,
        modifier = Modifier.size(20.dp)
      )
      Spacer(modifier = Modifier.width(6.dp))
      Text(
        text = sign.label,
        style = MaterialTheme.typography.bodyMedium,
        fontWeight = if (selected) FontWeight.SemiBold else FontWeight.Normal,
        color = when {
          isWarningSign -> MaterialTheme.colorScheme.onErrorContainer
          selected -> MaterialTheme.colorScheme.onPrimaryContainer
          else -> MaterialTheme.colorScheme.onSurface
        }
      )
    }
  }
}

private fun parseFlexibleDate(rawInput: String): LocalDate? {
  val trimmed = rawInput.trim()
  if (trimmed.isEmpty()) return null

  // If user appended onto existing ISO date (e.g. "2026-11-022026-09-15" from automated text input without clearing)
  val isoRegex = Regex("""\d{4}-\d{2}-\d{2}""")
  val allIsoMatches = isoRegex.findAll(trimmed).toList()
  if (allIsoMatches.isNotEmpty()) {
    val lastIso = allIsoMatches.last().value
    runCatching { return LocalDate.parse(lastIso) }
  }

  val formats = listOf(
    DateTimeFormatter.ISO_LOCAL_DATE,
    DateTimeFormatter.ofPattern("yyyy/M/d"),
    DateTimeFormatter.ofPattern("M/d/yyyy"),
    DateTimeFormatter.ofPattern("d/M/yyyy")
  )
  for (formatter in formats) {
    runCatching { return LocalDate.parse(trimmed, formatter) }
  }
  return null
}

